(function(){const endpoint='https://kiuhzrowbypovoydymam.supabase.co/rest/v1/wk_guest_posts?select=*&order=created_at.desc&limit=35',key='sb_publishable_USjBvA86ZzhKG9DMLX0SEg_AehbVr5M';let posts=[],time=0;const make=(tag,cls,text)=>{const x=document.createElement(tag);if(cls)x.className=cls;if(text)x.textContent=text;return x};const style=make('style');style.textContent='.guest-live-card{display:block;text-align:left;color:#243528;text-decoration:none}.guest-live-card .guest-live-thumb{display:block;aspect-ratio:1.02;border:2px solid #243528;border-radius:12px;overflow:hidden;box-shadow:5px 6px #243528;background:#e995ae}.guest-live-card .guest-live-thumb img{height:100%;width:100%;object-fit:cover}.guest-live-card h3{font-size:23px;margin:18px 0 4px}.guest-live-card p{margin:0;font-weight:750}.clip-rail:has(.guest-live-clip) .clip-card-placeholder{display:none}.guest-live-clip video{height:100%;width:100%;object-fit:cover}.guest-live-clip{position:relative;flex:0 0 clamp(220px,27vw,295px);aspect-ratio:9/16;background:#1d3525;border:2px solid #243528;border-radius:16px;overflow:hidden}.guest-live-clip label{position:absolute;bottom:12px;left:9px;right:9px;color:#fff;background:#20362cbd;font-weight:900;padding:8px;border-radius:7px}';document.head.append(style);function render(){const bands=document.querySelector('.bands-grid'),release=document.querySelector('.releases-grid'),clips=document.querySelector('.clip-rail');if(bands)for(const b of posts){if(bands.querySelector('[data-guest-id="'+b.id+'"]'))continue;const a=make('button','band-card guest-live-card');a.type='button';a.dataset.guestId=b.id;const pic=make('div','guest-live-thumb');const img=make('img');img.src=b.photo_url||'/assets/boombox-pose-1.webp';img.alt='Foto '+b.name;img.loading='lazy';pic.append(img);a.append(pic,make('h3','',b.name),make('p','',(b.genre||'Musik')+' / '+(b.city||'Purwokerto')));a.onclick=()=>{const rates=(b.rate_cards||[]).map(r=>r.label+': Rp'+Number(r.price||0).toLocaleString('id-ID')).join('\n');const content=[b.name,b.tagline,b.story,rates].filter(Boolean).join('\n\n');const d=make('dialog');d.style.cssText='max-width:min(620px,94vw);border:2px solid #243528;padding:28px;border-radius:15px;background:#fff9e6;color:#243528';const title=make('h2','',b.name),p=make('p','',content),close=make('button','','Tutup');close.onclick=()=>d.close();d.append(title,p,close);if(b.instagram_url){const link=make('a','','Instagram band ↗');link.href=b.instagram_url;link.target='_blank';link.rel='noopener noreferrer';d.append(link)}document.body.append(d);d.addEventListener('close',()=>d.remove());d.showModal()};bands.prepend(a)}if(release)for(const b of posts.filter(x=>x.release_title)){if(release.querySelector('[data-guest-release="'+b.id+'"]'))continue;const a=make('a','release-card guest-live-card');a.dataset.guestRelease=b.id;a.href=b.release_listen_url||'#band';a.target=b.release_listen_url?'_blank':'_self';a.rel='noopener noreferrer';const pic=make('div','guest-live-thumb'),im=make('img');im.src=b.release_cover_url||'/assets/melting-vinyl.webp';im.alt=b.release_title;pic.append(im);a.append(pic,make('h3','',b.release_title),make('p','',b.name));release.prepend(a)}if(clips)for(const b of posts.filter(x=>x.clip_url)){if(clips.querySelector('[data-guest-video="'+b.id+'"]'))continue;const card=make('div','guest-live-clip');card.dataset.guestVideo=b.id;const video=make('video');video.src=b.clip_url;video.controls=true;video.loop=true;video.muted=true;video.playsInline=true;video.preload='metadata';const label=make('label','',b.clip_title||b.name);card.append(video,label);clips.prepend(card);const observer=new IntersectionObserver(es=>{for(const e of es){if(e.isIntersecting)video.play().catch(()=>{});else video.pause()}},{threshold:.45});observer.observe(card)}}async function refresh(){try{const r=await fetch(endpoint,{headers:{apikey:key}});if(r.ok){posts=await r.json();render()}}catch(e){console.warn('Wingking guest content',e)}}const obs=new MutationObserver(()=>{if(Date.now()-time>1200){time=Date.now();render()}});obs.observe(document.documentElement,{childList:true,subtree:true});refresh()})();